def total_transformed(lst):
    """
    Iterate over lst by index i. If i is a multiple of 3 (i % 3 == 0), add lst[i]**2;
    else if i is a multiple of 4 (i % 4 == 0), add lst[i]**3;
    otherwise add lst[i]. Note: index 0 counts as a multiple of 3.
    Returns the total sum.
    """
    return sum((val * val) if (i % 3 == 0) else ((val ** 3) if (i % 4 == 0) else val)
               for i, val in enumerate(lst))

