def tribonacci(n, memo=None):
    if memo is None:
        memo = {0: 0, 1: 0, 2: 1}
    if n in memo:
        return memo[n]
    memo[n] = tribonacci(n-1, memo) + tribonacci(n-2, memo) + tribonacci(n-3, memo)
    return memo[n]

def main():
    try:
        n = int(input("Enter n: ").strip())
        if n < 0:
