import sys

def is_prime(n):
    """Check if a number is prime."""
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    i = 3
    while i * i <= n:
        if n % i == 0:
            return False
        i += 2
    return True

def get_prime_factors(n):
    """Get list of prime factors with repetition."""
    if n < 2:
        return []
    factors = []
    d = 2
    while d * d <= n:
        while n % d == 0:
            factors.append(d)
            n //= d
        d += 1 if d == 2 else 2
    if n > 1:
        factors.append(n)
    return factors

def is_product_of_three_primes(n):
    """
    Check if n is a product of exactly 3 primes.
    Returns True if n = p * q * r where p, q, r are primes (not necessarily distinct).
    """
    if n < 2:
        return False

    factors = get_prime_factors(n)

    # Must have exactly 3 prime factors (counting multiplicity)
    if len(factors) != 3:
        return False

    # All factors must be prime (get_prime_factors guarantees this)
    return all(is_prime(f) for f in factors)

