def count_parentheses(text: str) -> dict:
    """
    Counts parentheses in the given text and checks if they are balanced.

    Args:
        text: The string to analyze.

    Returns:
        A dictionary containing:
        - 'balanced': Boolean indicating if pairs are balanced.
        - 'counts': Dictionary with counts for '()', '[]', '{}'.
        - 'stack': List of unmatched opening parentheses (if any).
    """
    pairs = {'(': ')', '[': ']', '{': '}'}
    counts = {'()': 0, '[]': 0, '{}': 0}
    stack = []
    is_balanced = True

    for char in text:
        if char in pairs:
            stack.append(char)
        elif char in pairs.values():
            if not stack:
                is_balanced = False
                break
            opening = stack.pop()
            if pairs[opening] != char:
                is_balanced = False
                break
            pair = opening + char
            counts[pair] += 1

    if stack:
        is_balanced = False

    return {
        'balanced': is_balanced,
        'counts': counts,
        'stack': stack
    }

