import sys
import re

def count_odd_lower(token: str) -> int:
    """Count lowercase letters at odd positions (1‑based) in the token."""
    return sum(1 for i, ch in enumerate(token, start=1)
               if i % 2 == 1 and ch.islower())

def main() -> None:
    data = sys.stdin.read()
    # Split on whitespace or comma
    tokens = re.split(r'[,\s]+', data.strip())
    results = [str(count_odd_lower(tok)) for tok in tokens if tok]
    if results:
        print(' '.join(results))

if __name__ == "__main__":
    main()

